import{_ as e,o as s,c as o,a2 as t}from"./chunks/framework.DoCD98hS.js";const u=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":null}'),n={name:"guide/introduction.md"};function l(i,a,c,r,p,d){return s(),o("div",null,[...a[0]||(a[0]=[t(`<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>Melt JS（<code>hel-components</code>）围绕一件事组织：<strong>从应用里提取公共组件，让多个应用复用同一份远程能力，同时尽量保持本地开发体验。</strong></p><p>应用负责页面、路由、状态与业务编排；公共组件和通用能力独立维护，适合远程交付的部分通过 Hel 加载。不把每个业务页面都变成远程模块，也不要求仓库内所有包都远程化。</p><h2 id="两种加载方式-一套开发体验" tabindex="-1">两种加载方式，一套开发体验 <a class="header-anchor" href="#两种加载方式-一套开发体验" aria-label="Permalink to &quot;两种加载方式，一套开发体验&quot;">​</a></h2><ul><li><strong>高频组件预加载</strong>：导航、布局、常用表单等在启动阶段准备好，业务层继续 <code>import x from &#39;@melt-js/xxx&#39;</code>，不必到处编写远程加载代码。</li><li><strong>低频组件懒加载</strong>：偶发弹窗、重型图表、领域扩展等在真正使用时加载，目标是几行代码即可接入，并内置加载态、报错 fallback 等默认行为。</li></ul><p>两者应复用同一套底层加载、地址解析和错误规范，不各自维护一套远程协议。预加载仍有网络成本，只是把等待前置到启动阶段；懒加载的粒度取决于远程包的拆分，不等于每个组件天然独立下载。</p><h2 id="模块如何配合" tabindex="-1">模块如何配合 <a class="header-anchor" href="#模块如何配合" aria-label="Permalink to &quot;模块如何配合&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>业务应用（demo / tpl / 你的项目）</span></span>
<span class="line"><span>  ├─ 高频：启动预加载 → 像本地包一样 import</span></span>
<span class="line"><span>  └─ 低频：首次使用 → 框架适配层 → 默认加载态 / 错误兜底</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>                  libs-core（通用加载能力）</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>               远程 libs / comps（公共能力）</span></span></code></pre></div><p><code>libs-core-vue2</code>、<code>libs-core-vue3</code>、<code>libs-core-react</code> 已提供框架适配和 <code>defineHelComponent</code>。各包迁移进度与具体导出仍以实现为准，参见 <a href="./../modules/catalog/core.html">Core 专题</a>。</p><h2 id="文档怎么读" tabindex="-1">文档怎么读 <a class="header-anchor" href="#文档怎么读" aria-label="Permalink to &quot;文档怎么读&quot;">​</a></h2><ol><li><a href="./getting-started.html">快速上手</a>：先跑一个现有示例，再理解普通 import 与预加载的关系。</li><li><a href="./loading.html">预加载与懒加载</a>：决定哪些模块应该提前准备，哪些按需获取。</li><li><a href="./core.html">核心分层与 API 收敛</a>：约定能力该沉到哪里，避免重复实现。</li><li><a href="./../modules/">模块总览</a>：按职责查找现有模块；Bag 的完整专题继续由 <code>docs-bag</code> 承载。</li></ol><div class="tip custom-block"><p class="custom-block-title">当前阶段</p><p><code>libs-core</code> 已提供统一 <code>{ type, base, deps }</code> 预加载与同协议按需加载；框架 UI 适配仍待沉淀。仓库中的新入口需要随新版核心发布后才能从 registry 安装使用，不能把旧版本视作已包含这些 API。</p></div>`,12)])])}const m=e(n,[["render",l]]);export{u as __pageData,m as default};
